package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Paired instrumentation protocol; emulated timings are not ARM32 benchmarks. */
public class PerformanceAuditChecks extends Instrumentation {
 LauncherActivity a;Bundle args;SharedPreferences prefs;Map<String,?> saved;int checks;JSONObject report=new JSONObject();
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;}
 long stat(String name){try{return Long.parseLong(Debug.getRuntimeStat(name));}catch(Exception unsupported){return -1;}}
 JSONObject memory()throws Exception{Debug.MemoryInfo m=new Debug.MemoryInfo();Debug.getMemoryInfo(m);Runtime r=Runtime.getRuntime();return new JSONObject().put("pss_kib",m.getTotalPss()).put("java_used_bytes",r.totalMemory()-r.freeMemory()).put("gc_count",stat("art.gc.gc-count")).put("allocated_bytes",stat("art.gc.bytes-allocated")).put("elapsed_cpu_ms",android.os.Process.getElapsedCpuTime());}
 final class Watch implements TextWatcher{int events;public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){}public void afterTextChanged(Editable e){events++;}}
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  String phase=args.getString("phase","after");prefs=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(prefs.getAll());long started=SystemClock.elapsedRealtime();
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));CountDownLatch loaded=new CountDownLatch(1);a.worker.execute(()->a.main.post(loaded::countDown));check(loaded.await(45,TimeUnit.SECONDS),"discovery barrier");waitForIdleSync();long ready=SystemClock.elapsedRealtime();
  ui(()->{new GlassAppearance(0,45,1,0,1,false,true).save(a);a.prefs.edit().putBoolean("calendar",true).putBoolean("jakim",true).putInt("dock_size",0).apply();a.page="home";a.panelVisible=false;a.render();a.main.removeCallbacks(a.ticker);a.updateClock();});
  Thread.sleep(700);report.put("phase",phase).put("protocol","API27x86_64 TCG; motionOff BALANCED45%; synthetic60 updateClock calls and actual10s idle; timings include instrumentation").put("activity_to_worker_ready_ms",ready-started).put("memory_start",memory());
  Watch watch=new Watch();ui(()->{a.clock.addTextChangedListener(watch);a.date.addTextChangedListener(watch);a.statusTime.addTextChangedListener(watch);});JSONArray rounds=new JSONArray();
  for(int r=0;r<5;r++){JSONObject row=new JSONObject();ui(()->{try{a.main.removeCallbacks(a.ticker);long minute=System.currentTimeMillis()/60000,allocated=stat("art.gc.bytes-allocated"),gc=stat("art.gc.gc-count"),cpu=Debug.threadCpuTimeNanos(),wall=SystemClock.elapsedRealtimeNanos();int events=watch.events;for(int n=0;n<60;n++)a.updateClock();row.put("same_minute",minute==System.currentTimeMillis()/60000).put("ui_thread_cpu_ns",Debug.threadCpuTimeNanos()-cpu).put("wall_ns",SystemClock.elapsedRealtimeNanos()-wall).put("text_change_events",watch.events-events).put("allocated_bytes_delta",allocated<0?-1:stat("art.gc.bytes-allocated")-allocated).put("gc_count_delta",gc<0?-1:stat("art.gc.gc-count")-gc);}catch(Exception e){throw new RuntimeException(e);}});rounds.put(row);}
  report.put("clock_bursts",rounds);final int[] draws={0},layouts={0};ViewTreeObserver.OnDrawListener draw=()->draws[0]++;ViewTreeObserver.OnGlobalLayoutListener layout=()->layouts[0]++;final int[] before={0};
  ui(()->{before[0]=watch.events;a.stage.getViewTreeObserver().addOnDrawListener(draw);a.stage.getViewTreeObserver().addOnGlobalLayoutListener(layout);a.ticker.run();});long idleStart=SystemClock.elapsedRealtime();Thread.sleep(10000);ui(()->{a.main.removeCallbacks(a.ticker);a.stage.getViewTreeObserver().removeOnDrawListener(draw);a.stage.getViewTreeObserver().removeOnGlobalLayoutListener(layout);});report.put("idle10s",new JSONObject().put("elapsed_ms",SystemClock.elapsedRealtime()-idleStart).put("text_change_events",watch.events-before[0]).put("draw_callbacks",draws[0]).put("layout_callbacks",layouts[0]));
  JSONArray opens=new JSONArray();for(int n=0;n<5;n++){CountDownLatch frame=new CountDownLatch(1);long[] timing=new long[3];ui(()->{timing[0]=SystemClock.elapsedRealtimeNanos();a.controlCenter();timing[1]=SystemClock.elapsedRealtimeNanos();View decor=a.quickControls.dialog.getWindow().getDecorView();decor.getViewTreeObserver().addOnDrawListener(()->{if(timing[2]==0){timing[2]=SystemClock.elapsedRealtimeNanos();frame.countDown();}});});check(frame.await(30,TimeUnit.SECONDS),"CC first draw callback");opens.put(new JSONObject().put("construction_ns",timing[1]-timing[0]).put("first_draw_start_ns",timing[2]-timing[0]));ui(a.quickControls::close);}
  report.put("control_center_open",opens);long[] appearance={0};ui(()->{appearance[0]=SystemClock.elapsedRealtimeNanos();new DashSettings(a).open("Appearance");});long until=SystemClock.elapsedRealtime()+30000;while((a.appearanceEditor==null||!a.appearanceEditor.cacheReady)&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);check(a.appearanceEditor!=null&&a.appearanceEditor.cacheReady,"appearance ready");report.put("appearance_editor_ready_ns",SystemClock.elapsedRealtimeNanos()-appearance[0]);JSONArray edits=new JSONArray();
  for(int value:new int[]{35,55,45}){CountDownLatch frame=new CountDownLatch(1);long[] at={0,0};ui(()->{at[0]=SystemClock.elapsedRealtimeNanos();a.appearanceEditor.change(1,value);a.appearanceEditor.root.getViewTreeObserver().addOnDrawListener(()->{if(at[1]==0&&a.appearanceEditor!=null&&!a.appearanceEditor.renderPending){at[1]=SystemClock.elapsedRealtimeNanos();frame.countDown();}});});check(frame.await(30,TimeUnit.SECONDS),"appearance first draw");edits.put(new JSONObject().put("transparency",value).put("first_draw_start_ns",at[1]-at[0]));}
  report.put("appearance_edits",edits);ui(()->{a.appearanceEditor.cancel();a.main.removeCallbacks(a.ticker);});report.put("memory_end",memory());Runtime.getRuntime().gc();Thread.sleep(700);report.put("memory_after_gc_request",memory());
  try(Writer out=new FileWriter(new File(a.getFilesDir(),"qa-performance-"+phase+".json"))){out.write(report.toString(2));}result.putString("stream","PASS: "+checks+" performance protocol checks\n"+report.toString(2)+"\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+checks+": "+e+"\n"+report);}finally{if(prefs!=null&&saved!=null)AppearanceChecks.restore(prefs,saved);if(a!=null)ui(()->{if(a.quickControls!=null)a.quickControls.close();if(a.appearanceEditor!=null)a.appearanceEditor.close();a.finish();});}finish(code,result);}
}
